const fs = require('fs');
const path = require('path');
const { RESOURCE_GROUPS } = require('../src/locales/resourceGroups');
const { LOCALE_CODES } = require('../src/locales/localeConfig');
const { buildLocaleResources } = require('../src/locales/localeResourcesBuilder');
const root = path.resolve(__dirname, '../src/locales');
const GENERATED_LOADERS = path.join(root, 'localeResources.generated.js');
const check = process.argv.includes('--check');

require('./generate-hk-locale.js');
require('./generate-korean-locale.js');

const generatedLines = [
  '// Generated by scripts/generate-locale-resources.js. Do not edit by hand.',
];
const commonEntries = [];
const routeEntries = [];

for (const lang of LOCALE_CODES) {
  const common = JSON.parse(fs.readFileSync(path.join(root, lang, 'translation.json'), 'utf8'));
  const resources = buildLocaleResources(common, RESOURCE_GROUPS);
  const dir = path.join(root, 'resources', lang);
  if (!check) fs.mkdirSync(dir, { recursive: true });
  commonEntries.push(`  ${JSON.stringify(lang)}: () => import('./resources/${lang}/common.json')`);
  const groups = Object.keys(resources).filter(group => group !== 'common');
  routeEntries.push([
    `  ${JSON.stringify(lang)}: {`,
    ...groups.map((group, index) => `    ${JSON.stringify(group)}: () => import('./resources/${lang}/${group}.json')${index < groups.length - 1 ? ',' : ''}`),
    '  }',
  ].join('\n'));
  for (const [group, data] of Object.entries(resources)) {
    const filename = path.join(dir, `${group}.json`);
    const expected = JSON.stringify(data) + '\n';
    if (check) {
      if (!fs.existsSync(filename) || fs.readFileSync(filename, 'utf8') !== expected) {
        throw new Error(`Stale locale resource: ${lang}/${group}. Run scripts/generate-locale-resources.js.`);
      }
    } else fs.writeFileSync(filename, expected);
  }
}

generatedLines.push(
  '',
  'export const commonLocaleLoaders = {',
  commonEntries.join(',\n'),
  '};',
  '',
  'export const routeLocaleLoaders = {',
  `${routeEntries.join(',\n')}`,
  '};',
  '',
);
const generatedSource = generatedLines.join('\n');
if (check) {
  if (!fs.existsSync(GENERATED_LOADERS) || fs.readFileSync(GENERATED_LOADERS, 'utf8') !== generatedSource) {
    throw new Error('Stale locale loader registry. Run scripts/generate-locale-resources.js.');
  }
} else {
  fs.writeFileSync(GENERATED_LOADERS, generatedSource);
}

console.log(`Locale resources ${check ? 'verified' : 'generated'} for ${LOCALE_CODES.length} locale(s): ${LOCALE_CODES.join(', ')}.`);
